import { MD3DarkTheme } from 'react-native-paper';

export const theme = {
  ...MD3DarkTheme,
  colors: {
    ...MD3DarkTheme.colors,
    primary: '#4CAF50',
    accent: '#81C784',
    background: '#1a1a1a',
    surface: '#2a2a2a',
    text: '#ffffff',
    error: '#FF5252',
  },
};
